{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana Rent Stabilization Ordinance rent increase cap","requirement":"A landlord may not raise rent by more than the lesser of 3% of the current rent or 80% of the CPI change each year; for September 1, 2026 through August 31, 2027 the maximum allowable increase is 2.87%.","key_value":"lesser of 3% or 80% of CPI change; 2.87% for the period September 1, 2026 through August 31, 2027","coverage_conditions":"Rent increases for rental units covered by the Rent Stabilization and Just Cause Eviction Ordinance; the page states no building age, unit-count or owner limits.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":"Tenant may file a Tenant Petition to request review of a rent increase above the maximum allowable amount.","effective_date":"2026-09-01","valid_through":"2027-08-31","citation":"Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"The increase cannot be more than 3% of your current rent or 80% of the Consumer Price Index (CPI) change, whichever is less.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana Just Cause Eviction requirements","requirement":"A landlord must have a valid reason to end a tenancy, such as nonpayment of rent, breaking the lease, or the landlord moving into the property; for certain reasons the landlord may owe relocation assistance.","key_value":null,"coverage_conditions":"Residential tenancies covered by the Rent Stabilization and Just Cause Eviction Ordinance; the page states no building age, unit-count or owner limits.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"Your landlord must have a valid reason to evict you. This could be for not paying rent, breaking the lease, or if the landlord wants to move into the property themselves.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D084-01","n_rules":2,"note":null}

